import { initTRPC } from "@trpc/server";

// Initialize tRPC using initTRPC.create()
const t = initTRPC.create();

// Export the router and procedure helpers
export const router = t.router;
export const publicProcedure = t.procedure;

import { z } from "zod";
import { publicProcedure, router } from "../trpc";

// Define the appRouter with a single `hello` query procedure
export const appRouter = router({
  hello: publicProcedure
    // Accept a string input validated with zod
    .input(z.string())
    // Return "Hello ${input}"
    .query(({ input }) => {
      return `Hello ${input}`;
    }),
});

// Export the type of the appRouter for type-safe usage on the client
export type AppRouter = typeof appRouter;

import { fetchRequestHandler } from "@trpc/server/adapters/fetch";
import { appRouter } from "@/server/routers/_app";

// Set up the route handlers for the tRPC API using Next.js App Router Route Handlers
const handler = (req: Request) =>
  fetchRequestHandler({
    endpoint: "/api/trpc",
    req,
    router: appRouter,
    // Enable error messages in development
    onError:
      process.env.NODE_ENV === "development"
        ? ({ path, error }) => {
            console.error(`❌ tRPC failed on ${path ?? "<no-path>"}`, error);
          }
        : undefined,
  });

export { handler as GET, handler as POST };

"use client";

import { createTRPCReact } from "@trpc/react-query";
import type { AppRouter } from "@/server/routers/_app";

// Create the tRPC React Query client
export const trpc = createTRPCReact<AppRouter>();

"use client";

import { useState } from "react";
import { QueryClient, QueryClientProvider } from "@tanstack/react-query";
import { httpBatchLink } from "@trpc/client";
import { trpc } from "@/utils/trpc";

// Provider component that sets up QueryClient and trpc.Provider with an httpBatchLink pointing to /api/trpc
export function Provider({ children }: { children: React.ReactNode }) {
  const [queryClient] = useState(() => new QueryClient());
  const [trpcClient] = useState(() =>
    trpc.createClient({
      links: [
        httpBatchLink({
          url: "/api/trpc",
        }),
      ],
    }),
  );

  return (
    <trpc.Provider client={trpcClient} queryClient={queryClient}>
      <QueryClientProvider client={queryClient}>{children}</QueryClientProvider>
    </trpc.Provider>
  );
}

